// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(this));
        c.initialize();
        c.transferOwnership(newOwner);
        assertEq(c.owner(), newOwner);
        vm.prank(newOwner);
        try c.transferOwnership(address(0)) {
            assertTrue(c.owner() != address(0));
        } catch {
            assertTrue(true);
        }
    }
}
